import itertools
import json

# Works: (name, origin, genre) where origin is F/R and genre is N (novel) or P (play)
WORKS = [
    ("Fn1", "F", "N"), ("Fn2", "F", "N"), ("Fn3", "F", "N"),
    ("Rn1", "R", "N"), ("Rn2", "R", "N"), ("Rn3", "R", "N"),
    ("Fp1", "F", "P"), ("Fp2", "F", "P"),
    ("Rp1", "R", "P"),
]


def counts(sel):
    c = {"FN": 0, "RN": 0, "FP": 0, "RP": 0}
    for _, origin, genre in sel:
        c[origin + genre] += 1
    c["P"] = c["FP"] + c["RP"]
    c["N"] = c["FN"] + c["RN"]
    c["F"] = c["FN"] + c["FP"]
    return c


def valid(sel):
    if not (5 <= len(sel) <= 6):
        return False
    c = counts(sel)
    if c["F"] > 4:                      # no more than four French works
        return False
    if not (3 <= c["N"] <= 4):          # three to four novels
        return False
    if c["FN"] < c["RN"]:               # French novels >= Russian novels
        return False
    if c["FP"] == 2 and c["RP"] >= 1:   # both French plays -> no Russian play
        return False
    return True


OPTIONS = {
    "A": lambda c: c["RN"] == 0 and c["P"] == 1,
    "B": lambda c: c["RN"] == 1 and c["FP"] == 2,
    "C": lambda c: c["FN"] == 2 and c["RP"] == 1,
    "D": lambda c: c["FN"] == 2 and c["P"] == 2,
    "E": lambda c: c["RN"] == 2 and c["P"] == 1,
}

witness_count = {k: 0 for k in OPTIONS}
total_valid = 0

for size in (5, 6):
    for sel in itertools.combinations(WORKS, size):
        if not valid(sel):
            continue
        total_valid += 1
        c = counts(sel)
        for letter, pred in OPTIONS.items():
            if pred(c):
                witness_count[letter] += 1

possible = [k for k, v in witness_count.items() if v > 0]
impossible = [k for k in OPTIONS if witness_count[k] == 0]

if len(impossible) == 1:
    final_answer = impossible[0]
else:
    final_answer = "UNSUPPORTED"

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "valid_selections": total_valid,
        "witness_counts": witness_count,
        "possible_options": possible,
        "impossible_options": impossible,
    },
}, separators=(",", ":")))
